const passport = require('passport');
const CustomStrategy = require('passport-custom').Strategy;
const { UserModel } = require('../models/User');

passport.use('impersonate-token', new CustomStrategy(async (req, done) => {
  if (!req.user || req.user.role !== 'SUPER_ADMIN') {
    return done(null, false, { message: 'Forbidden: only super administrators may impersonate users' });
  }

  const targetUserId = req.headers['x-target-user-id'] || req.body.targetUserId;
  if (!targetUserId) {
    return done(null, false, { message: 'Missing target user ID' });
  }

  const user = await UserModel.findById(targetUserId);
  if (!user) {
    return done(null, false, { message: 'User not found' });
  }

  return done(null, user);
}));
